package com.inventoryhover;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * Floating chart of recent clicks: a clean click rate at the top, one stacked
 * bar per few seconds (good, missed, refused, double), and a legend with the
 * counts for the window. Movable like any RuneLite overlay box.
 */
class ClickChartOverlay extends Overlay
{
	private static final int WIDTH = 190;
	private static final int PAD = 6;
	private static final int CHART_HEIGHT = 50;
	private static final int BAR_GAP = 1;

	private static final Color GOOD = new Color(80, 200, 120);
	private static final Color MISSED = new Color(230, 70, 70);
	private static final Color REFUSED = new Color(240, 200, 40);
	private static final Color DOUBLE = new Color(240, 130, 40);
	private static final Color AXIS = new Color(255, 255, 255, 60);
	private static final Color LABEL = new Color(200, 200, 200);

	// Draw order from the baseline up; misses sit on top so they stand out
	private static final Color[] STACK = {GOOD, DOUBLE, REFUSED, MISSED};
	private static final String[] NAMES = {"Good", "Double", "Refused", "Missed"};

	private final InventoryHoverHighlightPlugin plugin;
	private final InventoryHoverHighlightConfig config;

	@Inject
	ClickChartOverlay(InventoryHoverHighlightPlugin plugin, InventoryHoverHighlightConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.clickChart())
		{
			return null;
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int[][] history = plugin.stats.history();

		// Per bar: good, double, refused, missed. Good excludes the clicks that went wrong.
		int[][] bars = new int[history.length][4];
		int[] totals = new int[4];
		for (int i = 0; i < history.length; i++)
		{
			int[] h = history[i];
			int useful = h[ClickStats.Kind.USEFUL.ordinal()];
			int doubles = h[ClickStats.Kind.DOUBLE.ordinal()];
			int refused = h[ClickStats.Kind.REJECTED.ordinal()];
			int missed = h[ClickStats.Kind.MISSED.ordinal()];
			bars[i][0] = Math.max(0, useful - doubles - refused);
			bars[i][1] = doubles;
			bars[i][2] = refused;
			bars[i][3] = missed;
			for (int k = 0; k < 4; k++)
			{
				totals[k] += bars[i][k];
			}
		}

		Font small = FontManager.getRunescapeSmallFont();
		Font bold = FontManager.getRunescapeBoldFont();
		graphics.setFont(small);
		FontMetrics smallMetrics = graphics.getFontMetrics(small);
		FontMetrics boldMetrics = graphics.getFontMetrics(bold);
		int lineHeight = smallMetrics.getHeight();

		int titleHeight = boldMetrics.getHeight();
		int legendHeight = lineHeight * 2;
		int height = PAD + titleHeight + 4 + CHART_HEIGHT + lineHeight + 4 + legendHeight + PAD;

		graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		graphics.fill(new RoundRectangle2D.Float(0, 0, WIDTH, height, 8, 8));

		// Title and clean click rate
		int y = PAD + boldMetrics.getAscent();
		graphics.setFont(bold);
		graphics.setColor(Color.WHITE);
		long seconds = ClickStats.BUCKET_MILLIS * ClickStats.BUCKETS / 1000;
		graphics.drawString("Clicks, last " + seconds + "s", PAD, y);

		int all = totals[0] + totals[1] + totals[2] + totals[3];
		String rate = all == 0 ? "-" : (totals[0] * 100 / all) + "% clean";
		graphics.setColor(all == 0 ? LABEL : rateColor(totals[0] * 100 / all));
		graphics.drawString(rate, WIDTH - PAD - boldMetrics.stringWidth(rate), y);

		// Bars
		int chartTop = PAD + titleHeight + 4;
		int chartBottom = chartTop + CHART_HEIGHT;
		int max = 1;
		for (int[] bar : bars)
		{
			max = Math.max(max, bar[0] + bar[1] + bar[2] + bar[3]);
		}

		int chartWidth = WIDTH - PAD * 2;
		float slot = (float) chartWidth / bars.length;
		for (int i = 0; i < bars.length; i++)
		{
			int x = PAD + Math.round(i * slot);
			int w = Math.max(1, Math.round((i + 1) * slot) - Math.round(i * slot) - BAR_GAP);
			int top = chartBottom;
			for (int k = 0; k < 4; k++)
			{
				int h = Math.round((float) bars[i][k] / max * CHART_HEIGHT);
				if (h <= 0)
				{
					continue;
				}
				top -= h;
				graphics.setColor(STACK[k]);
				graphics.fillRect(x, top, w, h);
			}
		}

		graphics.setColor(AXIS);
		graphics.drawLine(PAD, chartBottom, WIDTH - PAD, chartBottom);

		graphics.setFont(small);
		if (all == 0)
		{
			String empty = "No clicks yet";
			graphics.setColor(LABEL);
			graphics.drawString(empty, (WIDTH - smallMetrics.stringWidth(empty)) / 2,
				chartTop + CHART_HEIGHT / 2 + smallMetrics.getAscent() / 2);
		}

		// Time axis
		y = chartBottom + smallMetrics.getAscent() + 1;
		graphics.setColor(LABEL);
		graphics.drawString(seconds + "s ago", PAD, y);
		String now = "now";
		graphics.drawString(now, WIDTH - PAD - smallMetrics.stringWidth(now), y);

		// Legend: two columns, colored square and count
		int legendTop = chartBottom + lineHeight + 4;
		int column = (WIDTH - PAD * 2) / 2;
		for (int k = 0; k < 4; k++)
		{
			int x = PAD + (k % 2) * column;
			int rowY = legendTop + (k / 2) * lineHeight;
			graphics.setColor(STACK[k]);
			graphics.fillRect(x, rowY + 2, 7, 7);
			graphics.setColor(Color.WHITE);
			graphics.drawString(NAMES[k] + " " + totals[k], x + 11, rowY + smallMetrics.getAscent());
		}

		return new Dimension(WIDTH, height);
	}

	private static Color rateColor(int percent)
	{
		return percent >= 90 ? GOOD : percent >= 75 ? REFUSED : MISSED;
	}
}

package com.inventoryhover;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Recent click counts split into fixed time buckets for the click chart. Written on the client thread and read on
 * the Swing thread, so every access is synchronized.
 */
class ClickStats
{
	enum Kind
	{
		/** A click the game accepted on a slot, prayer or spell. */
		USEFUL,
		/** A click on an empty slot or a gap. */
		MISSED,
		/** A click the game refused with a message. */
		REJECTED,
		/** A second click on the same slot in one tick. */
		DOUBLE
	}

	static final long BUCKET_MILLIS = 5_000;
	static final int BUCKETS = 24;

	static class Bucket
	{
		final long start;
		final int[] counts = new int[Kind.values().length];

		Bucket(long start)
		{
			this.start = start;
		}
	}

	private final Deque<Bucket> buckets = new ArrayDeque<>();

	synchronized void add(Kind kind)
	{
		long start = System.currentTimeMillis() / BUCKET_MILLIS * BUCKET_MILLIS;
		Bucket last = buckets.peekLast();
		if (last == null || last.start != start)
		{
			last = new Bucket(start);
			buckets.addLast(last);
		}
		last.counts[kind.ordinal()]++;
		trim();
	}

	/** Counts per bucket for the last {@link #BUCKETS} buckets, oldest first; quiet buckets are zeros. */
	synchronized int[][] history()
	{
		trim();
		long newest = System.currentTimeMillis() / BUCKET_MILLIS * BUCKET_MILLIS;
		int[][] history = new int[BUCKETS][Kind.values().length];
		for (Bucket bucket : buckets)
		{
			int index = BUCKETS - 1 - (int) ((newest - bucket.start) / BUCKET_MILLIS);
			if (index >= 0 && index < BUCKETS)
			{
				history[index] = bucket.counts.clone();
			}
		}
		return history;
	}

	synchronized void reset()
	{
		buckets.clear();
	}

	private void trim()
	{
		long oldest = System.currentTimeMillis() - BUCKET_MILLIS * BUCKETS;
		while (!buckets.isEmpty() && buckets.peekFirst().start < oldest)
		{
			buckets.removeFirst();
		}
	}
}

package com.inventoryhover;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(InventoryHoverHighlightConfig.GROUP)
public interface InventoryHoverHighlightConfig extends Config
{
	String GROUP = "inventoryhoverhighlight";

	enum HighlightStyle
	{
		OUTLINE,
		FILL,
		BOTH
	}

	enum GridMode
	{
		OFF,
		IN_PANEL,
		ALWAYS
	}

	enum RingAnimation
	{
		GROW,
		SHRINK,
		PULSE,
		CROSS
	}

	enum CooldownStyle
	{
		FILL,
		DRAIN,
		DIM
	}

	enum TickCue
	{
		OFF,
		PULSE,
		DRAIN,
		COLOR
	}

	@ConfigSection(
		name = "Hover highlight",
		description = "How the highlight under the mouse looks",
		position = 0
	)
	String hoverSection = "hover";

	@ConfigSection(
		name = "Areas",
		description = "Where the highlight and clickable grid are shown",
		position = 1
	)
	String areasSection = "areas";

	@ConfigSection(
		name = "Click feedback",
		description = "Flash and marker on the slot you click",
		position = 2,
		closedByDefault = true
	)
	String clickSection = "click";

	@ConfigSection(
		name = "Missed clicks",
		description = "Markers for clicks that do nothing or are refused",
		position = 3,
		closedByDefault = true
	)
	String missSection = "misses";

	@ConfigSection(
		name = "Dead areas",
		description = "Shading over the gaps where a click does nothing, per panel",
		position = 4,
		closedByDefault = true
	)
	String deadSection = "dead";

	@ConfigSection(
		name = "Prayers and spells",
		description = "Active prayer, selected spell and autocast highlights",
		position = 5,
		closedByDefault = true
	)
	String prayerSection = "prayerspells";

	@ConfigSection(
		name = "Tick cue",
		description = "Timing cue on prayers to help with prayer flicking",
		position = 6,
		closedByDefault = true
	)
	String tickSection = "tick";

	@ConfigSection(
		name = "Click chart",
		description = "Floating chart of your recent good, missed, refused and double clicks",
		position = 7,
		closedByDefault = true
	)
	String chartSection = "stats";

	@ConfigSection(
		name = "Hide items",
		description = "Hide items you do not click in a fight",
		position = 8,
		closedByDefault = true
	)
	String itemsSection = "items";

	@ConfigSection(
		name = "Eat and drink delay",
		description = "Shade food and potions while another one would be ignored",
		position = 9,
		closedByDefault = true
	)
	String delaySection = "delays";

	@ConfigSection(
		name = "Spotlight",
		description = "Glow at the mouse that dims the panel outward",
		position = 10,
		closedByDefault = true
	)
	String spotlightSection = "spotlight";

	@ConfigSection(
		name = "Import/export settings",
		description = "Export all settings to the clipboard as JSON, or import shared JSON settings",
		position = 11,
		closedByDefault = true
	)
	String shareSection = "share";


	// Hover highlight

	@ConfigItem(
		keyName = "style",
		name = "Style",
		description = "How the hovered slot is drawn",
		position = 0,
		section = hoverSection
	)
	default HighlightStyle style()
	{
		return HighlightStyle.BOTH;
	}

	@Alpha
	@ConfigItem(
		keyName = "outlineColor",
		name = "Outline color",
		description = "Color of the slot outline",
		position = 1,
		section = hoverSection
	)
	default Color outlineColor()
	{
		return new Color(255, 255, 255, 120);
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColor",
		name = "Fill color",
		description = "Color of the slot fill",
		position = 2,
		section = hoverSection
	)
	default Color fillColor()
	{
		return new Color(98, 189, 125, 60);
	}

	@ConfigItem(
		keyName = "hideWhenMenuOpen",
		name = "Hide when right-click menu open",
		description = "Do not highlight while a right-click menu is open",
		position = 3,
		section = hoverSection
	)
	default boolean hideWhenMenuOpen()
	{
		return false;
	}

	@Units(Units.MILLISECONDS)
	@Range(max = 5000)
	@ConfigItem(
		keyName = "hoverFade",
		name = "Hover fade-out",
		description = "How long a highlight, including its tick cue, fades after the mouse leaves; 0 to disable",
		position = 4,
		section = hoverSection
	)
	default int hoverFade()
	{
		return 400;
	}

	@Units(Units.MILLISECONDS)
	@Range(max = 1000)
	@ConfigItem(
		keyName = "hoverDelay",
		name = "Hover delay",
		description = "How long the mouse must rest on an area before it is highlighted; 0 for instant",
		position = 5,
		section = hoverSection
	)
	default int hoverDelay()
	{
		return 0;
	}

	@Range(max = 10)
	@ConfigItem(
		keyName = "cornerRadius",
		name = "Corner radius",
		description = "Rounds the corners of the highlight; 0 for square",
		position = 6,
		section = hoverSection
	)
	default int cornerRadius()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "roundedAreas",
		name = "Round grid and dead areas to highlight radius",
		description = "Round the clickable grid and the dead area shading with the hover highlight's corner radius."
			+ "<br>Note: the game's clickable areas are square, so slot corners can look dead even though"
			+ " clicks there still work",
		position = 7,
		section = hoverSection
	)
	default boolean roundedAreas()
	{
		return true;
	}

	@Range(min = 1, max = 4)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline width",
		description = "Thickness of the outline in pixels",
		position = 8,
		section = hoverSection
	)
	default int outlineWidth()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "discoMode",
		name = "Disco mode",
		description = "Pick a random hover color every time the mouse moves to a new area",
		position = 9,
		section = hoverSection
	)
	default boolean discoMode()
	{
		return false;
	}

	// Areas

	@ConfigItem(
		keyName = "prayers",
		name = "Prayers",
		description = "Also highlight the hovered prayer in the prayer tab",
		position = 0,
		section = areasSection
	)
	default boolean prayers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "spells",
		name = "Spells",
		description = "Also highlight the hovered spell in the spellbook",
		position = 1,
		section = areasSection
	)
	default boolean spells()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bankInventory",
		name = "Bank inventory",
		description = "Also highlight the inventory shown next to the bank",
		position = 2,
		section = areasSection
	)
	default boolean bankInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "onlyItems",
		name = "Only slots with items",
		description = "Skip empty inventory slots",
		position = 3,
		section = areasSection
	)
	default boolean onlyItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "grid",
		name = "Clickable grid",
		description = "Outline every clickable area the hover highlight can fill."
			+ "<br>In panel: only the panel under the mouse"
			+ "<br>Always: every visible panel",
		position = 4,
		section = areasSection
	)
	default GridMode grid()
	{
		return GridMode.OFF;
	}

	@ConfigItem(
		keyName = "gridShowEmpty",
		name = "Grid on empty slots",
		description = "Also outline inventory slots with no item, so every clickable slot shows",
		position = 5,
		section = areasSection
	)
	default boolean gridShowEmpty()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "gridColor",
		name = "Grid color",
		description = "Color of the clickable grid outlines",
		position = 6,
		section = areasSection
	)
	default Color gridColor()
	{
		return new Color(255, 255, 255, 40);
	}

	// Click feedback

	@ConfigItem(
		keyName = "clickFlash",
		name = "Click flash",
		description = "Briefly flash the slot you clicked",
		position = 0,
		section = clickSection
	)
	default boolean clickFlash()
	{
		return true;
	}

	@ConfigItem(
		keyName = "clickMarker",
		name = "Queued click marker",
		description = "Mark a clicked slot with a dot until the next game tick. The dot is yellow"
			+ " (rejected click color) when the click lands during the eat or drink delay",
		position = 1,
		section = clickSection
	)
	default boolean clickMarker()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "clickFlashColor",
		name = "Flash color",
		description = "Color of the click flash",
		position = 2,
		section = clickSection
	)
	default Color clickFlashColor()
	{
		return new Color(255, 255, 255, 110);
	}

	@Units(Units.MILLISECONDS)
	@Range(min = 50, max = 1000)
	@ConfigItem(
		keyName = "clickFlashDuration",
		name = "Flash duration",
		description = "How long the click flash takes to fade",
		position = 3,
		section = clickSection
	)
	default int clickFlashDuration()
	{
		return 200;
	}

	@Alpha
	@ConfigItem(
		keyName = "clickMarkerColor",
		name = "Marker color",
		description = "Color of the queued click marker",
		position = 4,
		section = clickSection
	)
	default Color clickMarkerColor()
	{
		return new Color(0, 255, 0, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "doubleClickColor",
		name = "Double click color",
		description = "Marker color when the same slot is clicked twice in one tick",
		position = 5,
		section = clickSection
	)
	default Color doubleClickColor()
	{
		return new Color(255, 60, 60, 220);
	}

	// Missed clicks

	@ConfigItem(
		keyName = "deadClickMarker",
		name = "Dead click marker",
		description = "Show a red ring where you click an empty slot or a gap with no interaction",
		position = 0,
		section = missSection
	)
	default boolean deadClickMarker()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rejectedClickMarker",
		name = "Rejected click marker",
		description = "Show a yellow ring where a click reached the game but was refused,"
			+ " like equipping an item with no inventory space for the swap",
		position = 1,
		section = missSection
	)
	default boolean rejectedClickMarker()
	{
		return true;
	}

	@ConfigItem(
		keyName = "missDots",
		name = "Miss dots",
		description = "Leave a small dot at every dead click, so you can see where your misses land",
		position = 2,
		section = missSection
	)
	default boolean missDots()
	{
		return false;
	}

	@ConfigItem(
		keyName = "missOutline",
		name = "Miss outline",
		description = "Outline the slot nearest a dead click, the one you most likely meant to click."
			+ " It replaces the normal outline on that slot until it fades",
		position = 3,
		section = missSection
	)
	default boolean missOutline()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "misclickColor",
		name = "Dead click color",
		description = "Color of the dead click marker",
		position = 4,
		section = missSection
	)
	default Color misclickColor()
	{
		return new Color(255, 60, 60, 180);
	}

	@Alpha
	@ConfigItem(
		keyName = "rejectedClickColor",
		name = "Rejected click color",
		description = "Color of the rejected click marker",
		position = 5,
		section = missSection
	)
	default Color rejectedClickColor()
	{
		return new Color(255, 220, 0, 200);
	}

	@ConfigItem(
		keyName = "ringAnimation",
		name = "Ring animation",
		description = "How dead and rejected click markers animate."
			+ "<br>Grow: ring grows while it fades"
			+ "<br>Shrink: ring shrinks onto the click"
			+ "<br>Pulse: ring beats while it fades"
			+ "<br>Cross: an X instead of a ring",
		position = 6,
		section = missSection
	)
	default RingAnimation ringAnimation()
	{
		return RingAnimation.GROW;
	}

	@Units(Units.MILLISECONDS)
	@Range(min = 100, max = 3000)
	@ConfigItem(
		keyName = "ringDuration",
		name = "Ring duration",
		description = "How long dead and rejected click markers take to fade",
		position = 7,
		section = missSection
	)
	default int ringDuration()
	{
		return 500;
	}

	@Alpha
	@ConfigItem(
		keyName = "missDotColor",
		name = "Miss dot color",
		description = "Color of the miss dots",
		position = 8,
		section = missSection
	)
	default Color missDotColor()
	{
		return new Color(255, 40, 40, 200);
	}

	@Units(Units.SECONDS)
	@Range(min = 1, max = 600)
	@ConfigItem(
		keyName = "missDotDuration",
		name = "Miss dot duration",
		description = "How long each miss dot stays before it is gone; it fades over this time",
		position = 9,
		section = missSection
	)
	default int missDotDuration()
	{
		return 15;
	}

	@Alpha
	@ConfigItem(
		keyName = "missOutlineColor",
		name = "Miss outline color",
		description = "Color of the miss outline",
		position = 10,
		section = missSection
	)
	default Color missOutlineColor()
	{
		return new Color(255, 40, 40, 130);
	}

	@Units(Units.MILLISECONDS)
	@Range(min = 100, max = 10000)
	@ConfigItem(
		keyName = "missOutlineDuration",
		name = "Miss outline duration",
		description = "How long the miss outline stays before it is gone",
		position = 11,
		section = missSection
	)
	default int missOutlineDuration()
	{
		return 1500;
	}

	// Dead areas

	@ConfigItem(
		keyName = "deadAreas",
		name = "Dead areas",
		description = "Shade the gaps where a click does nothing."
			+ "<br>In panel: only the panel under the mouse"
			+ "<br>Always: every visible panel",
		position = 0,
		section = deadSection
	)
	default GridMode deadAreas()
	{
